  coeffVec[0] = 1.0 / proc_control_B.coeffVec_tmp * proc_control_B.posPts_idx_1
    + -2.0 / proc_control_rt_powd_snf(finalTime, 3.0) *
    proc_control_B.posPts_idx_0;
