  proc_control_B.qt[2] = -b_this->xl[5] / proc_control_B.t14_l;
  proc_control_B.qt[3] = -b_this->xl[6] / proc_control_B.t14_l;
  proc_control_quatmultiply(&y[3], proc_control_B.qt, &Z[3]);

