// Function for MATLAB Function: '<S220>/NLMPC'
real_T proc_control::proc_control_computeMeritFcn(real_T obj_penaltyParam,
  real_T fval, const real_T Cineq_workspace_data[], int32_T mIneq, const real_T
  Ceq_workspace[130], boolean_T evalWellDefined)
{
  real_T val;
  if (evalWellDefined) {
    proc_control_B.constrViolationEq_j = 0.0;
    for (proc_control_B.k_hk = 0; proc_control_B.k_hk < 130; proc_control_B.k_hk
         ++) {
      proc_control_B.constrViolationEq_j += std::abs
        (Ceq_workspace[proc_control_B.k_hk]);
    }

    proc_control_B.constrViolationIneq_k = 0.0;
    proc_control_B.k_hk = static_cast<uint16_T>(mIneq);
    for (proc_control_B.idx_nt = 0; proc_control_B.idx_nt < proc_control_B.k_hk;
         proc_control_B.idx_nt++) {
      proc_control_B.Cineq_workspace =
        Cineq_workspace_data[proc_control_B.idx_nt];
      if (proc_control_B.Cineq_workspace > 0.0) {
        proc_control_B.constrViolationIneq_k += proc_control_B.Cineq_workspace;
      }
    }

    val = (proc_control_B.constrViolationEq_j +
           proc_control_B.constrViolationIneq_k) * obj_penaltyParam + fval;
  } else {
    val = (rtInf);
  }

  return val;
}

// Function for MATLAB Function: '<S220>/NLMPC'
void proc_control::proc_control_linesearch(boolean_T *evalWellDefined, const
  real_T bineq_data[], int32_T WorkingSet_nVar, int32_T WorkingSet_ldA, const
  real_T WorkingSet_Aineq_data[], s_WVbWSSvCeJzx5TXXa9L1l_proc__T *TrialState,
  real_T MeritFunction_penaltyParam, real_T MeritFunction_phi, real_T
  MeritFunction_phiPrimePlus, real_T MeritFunction_phiFullStep, int32_T
  FcnEvaluator_next_next_next_nex, const s_qYIvDqP9yRqtt40IDZ89JG_proc_T
  *FcnEvaluator_next_next_next_n_0, const s_xJmQKnCTzvv6aUzMZcIqsF_proc_T
  *FcnEvaluator_next_next_next_n_1, boolean_T socTaken, real_T *alpha, int32_T
  *exitflag)
{
  int32_T exitg1;
  boolean_T exitg2;
  proc_control_B.mLinIneq_j = TrialState->mIneq - TrialState->mNonlinIneq;
  *alpha = 1.0;
  *exitflag = 1;
  proc_control_B.phi_alpha = MeritFunction_phiFullStep;
  if (WorkingSet_nVar - 1 >= 0) {
    std::memcpy(&TrialState->searchDir.data[0], &TrialState->delta_x.data[0],
                static_cast<uint32_T>(WorkingSet_nVar) * sizeof(real_T));
  }

  do {
    exitg1 = 0;
    if (TrialState->FunctionEvaluations < 13900) {
      if ((*evalWellDefined) && (proc_control_B.phi_alpha <= *alpha * 0.0001 *
           MeritFunction_phiPrimePlus + MeritFunction_phi)) {
        exitg1 = 1;
      } else {
        *alpha *= 0.7;
        proc_control_B.b_tmp_m = static_cast<uint16_T>(WorkingSet_nVar);
        for (proc_control_B.k_h = 0; proc_control_B.k_h < proc_control_B.b_tmp_m;
             proc_control_B.k_h++) {
          TrialState->delta_x.data[proc_control_B.k_h] = *alpha *
            TrialState->xstar.data[proc_control_B.k_h];
        }

        if (socTaken) {
          proc_control_B.phi_alpha = *alpha * *alpha;
          if ((WorkingSet_nVar >= 1) && (!(proc_control_B.phi_alpha == 0.0))) {
            for (proc_control_B.k_h = 0; proc_control_B.k_h < WorkingSet_nVar;
                 proc_control_B.k_h++) {
              TrialState->delta_x.data[proc_control_B.k_h] +=
                proc_control_B.phi_alpha * TrialState->
                socDirection.data[proc_control_B.k_h];
            }
          }
        }

        proc_control_B.tooSmallX = true;
        proc_control_B.k_h = 0;
        exitg2 = false;
        while ((!exitg2) && (proc_control_B.k_h <= static_cast<uint16_T>
                             (WorkingSet_nVar) - 1)) {
          if (0.1 * std::fmax(1.0, std::abs(TrialState->
                xstarsqp[proc_control_B.k_h])) <= std::abs
              (TrialState->delta_x.data[proc_control_B.k_h])) {
            proc_control_B.tooSmallX = false;
            exitg2 = true;
          } else {
            proc_control_B.k_h++;
          }
        }

        if (proc_control_B.tooSmallX) {
          *exitflag = -2;
          exitg1 = 1;
        } else {
          for (proc_control_B.k_h = 0; proc_control_B.k_h <
               proc_control_B.b_tmp_m; proc_control_B.k_h++) {
            TrialState->xstarsqp[proc_control_B.k_h] = TrialState->
              xstarsqp_old[proc_control_B.k_h] + TrialState->
              delta_x.data[proc_control_B.k_h];
          }

          proc_control_evalObjAndConstr(FcnEvaluator_next_next_next_nex,
            FcnEvaluator_next_next_next_n_0, FcnEvaluator_next_next_next_n_1,
            TrialState->xstarsqp, TrialState->cIneq.data, TrialState->iNonIneq0,
            TrialState->cEq, &TrialState->sqpFval, &proc_control_B.k_h);
          proc_con_computeLinearResiduals(TrialState->xstarsqp, WorkingSet_nVar,
            TrialState->cIneq.data, TrialState->cIneq.size,
            proc_control_B.mLinIneq_j, WorkingSet_Aineq_data, bineq_data,
            WorkingSet_ldA);
          TrialState->FunctionEvaluations++;
          *evalWellDefined = (proc_control_B.k_h == 1);
          proc_control_B.phi_alpha = proc_control_computeMeritFcn
            (MeritFunction_penaltyParam, TrialState->sqpFval,
             TrialState->cIneq.data, TrialState->mIneq, TrialState->cEq,
             *evalWellDefined);
        }
      }
    } else {
      *exitflag = 0;
      exitg1 = 1;
    }
  } while (exitg1 == 0);
}

